package com.surgetimer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SurgeTimerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SurgeTimerPlugin.class);
		RuneLite.main(args);
	}
}

package com.surgetimer;

import com.google.inject.Provides;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Surge Timer",
	description = "Puts a timer over the surge potion",
	tags = {"surge", "potion", "special", "attack", "spec", "cooldown", "timer", "adrenaline"}
)
public class SurgeTimerPlugin extends Plugin
{
	// Five minutes
	static final int COOLDOWN_TICKS = 500;
	// The server lowers the timer varbit by one every 10 ticks
	private static final int TICKS_PER_STEP = 10;

	private static final String COOLDOWN_MESSAGE = "You are still full of adrenaline.";
	private static final String READY_MESSAGE = "You now feel capable of drinking another dose of surge potion.";
	private static final Pattern MINUTES = Pattern.compile("(\\d+) minutes?\\.");
	private static final Pattern SECONDS = Pattern.compile("(\\d+) seconds?\\.");

	// The cooldown pauses when one of these ends, until the next one starts
	private static final Pattern COLOSSEUM_WAVE_END = Pattern.compile("Wave \\d+ completed! Wave duration:.*");
	private static final String INFERNO_WAVE_END = "Wave completed!";
	private static final Pattern TOB_ROOM_END = Pattern.compile("Wave '.+' .*complete!.*");
	private static final Pattern DOOM_LEVEL_END = Pattern.compile("Delve level: .+ duration:.*");
	private static final Pattern WAVE_START = Pattern.compile("Wave: \\d+");
	private static final String SOL_HEREDIT_START = "Sol Heredit jumps down from his seat";
	private static final int INFERNO_REGION = 9043;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SurgeTimerOverlay overlay;

	// Last value of the timer varbit
	private int varbit;
	// Ticks left on the cooldown, counted down locally between varbit changes
	@Getter
	private int ticksLeft;
	// Lowest the local count can go before the varbit changes again
	private int floor;
	// Whether the cooldown is paused, like between Colosseum waves
	private boolean paused;

	@Provides
	SurgeTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SurgeTimerConfig.class);
	}

	@Override
	protected void startUp()
	{
		varbit = 0;
		ticksLeft = 0;
		floor = 0;
		paused = false;
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				sync();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlay.clearCache();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (sync() || ticksLeft == 0 || paused)
		{
			return;
		}

		// Never count below what the varbit allows. If the cooldown pauses without it being
		// noticed, the varbit stops changing, so the timer stops here instead of running out.
		ticksLeft = Math.max(ticksLeft - 1, floor);
	}

	/**
	 * Reads the timer varbit, and restarts the local count if it changed. The varbit also
	 * covers the cooldown being removed, like on death or entering a raid.
	 *
	 * @return whether the varbit changed
	 */
	private boolean sync()
	{
		int value = client.getVarbitValue(VarbitID.SURGE_POTION_TIMER);
		if (value == varbit)
		{
			return false;
		}

		// The varbit only counts down one step at a time. A bigger drop means the cooldown was
		// removed, like by drinking from a house pool, which leaves it on 1 instead of 0.
		boolean removed = value > 0 && value < varbit - 1;
		varbit = value;
		// The varbit only changes while the cooldown is running
		paused = false;
		if (removed)
		{
			ticksLeft = 0;
			floor = 0;
			return true;
		}

		ticksLeft = value * TICKS_PER_STEP;
		floor = value > 0 ? ticksLeft - TICKS_PER_STEP + 1 : 0;
		return true;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if (message.startsWith(COOLDOWN_MESSAGE))
		{
			resync(message);
		}
		else if (message.equals(READY_MESSAGE))
		{
			ticksLeft = 0;
			floor = 0;
			paused = false;
		}
		else if (COLOSSEUM_WAVE_END.matcher(message).matches()
			|| TOB_ROOM_END.matcher(message).matches()
			|| DOOM_LEVEL_END.matcher(message).matches()
			// The Fight Caves say the same, but the cooldown doesn't pause there
			|| (message.equals(INFERNO_WAVE_END) && inInferno()))
		{
			paused = true;
		}
		else if (WAVE_START.matcher(message).matches() || message.contains(SOL_HEREDIT_START))
		{
			paused = false;
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// On while the fight in a Theatre of Blood room is going. It also turns off when leaving,
		// but leaving removes the cooldown anyway.
		if (event.getVarbitId() == VarbitID.TOB_CLIENT_WAVEPROGRESS_TYPE)
		{
			paused = event.getValue() == 0;
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		// Mokhaiotl appears when the next delve level starts
		if (event.getNpc().getId() == NpcID.DOM_BOSS)
		{
			paused = false;
		}
	}

	/**
	 * Trying to drink while on cooldown says how long is left, like "3 minutes." or "12 seconds.".
	 * The minutes are rounded, so they only give a range. The local count is moved into that
	 * range, and if the varbit says there's no cooldown at all, the message is trusted on its own.
	 */
	private void resync(String message)
	{
		int low;
		int high;
		Matcher seconds = SECONDS.matcher(message);
		Matcher minutes = MINUTES.matcher(message);
		if (seconds.find())
		{
			int s = Integer.parseInt(seconds.group(1));
			low = toTicks(s - 1) + 1;
			high = toTicks(s);
		}
		else if (minutes.find())
		{
			// Could be rounded up or to the nearest minute, so allow for both
			int m = Integer.parseInt(minutes.group(1));
			low = toTicks((m - 1) * 60) + 1;
			high = toTicks(m * 60 + 29);
		}
		else
		{
			return;
		}

		if (varbit > 0)
		{
			// The varbit is exact to 10 ticks, so it narrows the range further
			low = Math.max(low, floor);
			high = Math.min(high, varbit * TICKS_PER_STEP);
			if (low > high)
			{
				return;
			}
		}
		else
		{
			floor = 0;
		}

		ticksLeft = ticksLeft == 0 ? high : Math.max(low, Math.min(high, ticksLeft));
	}

	private boolean inInferno()
	{
		Player player = client.getLocalPlayer();
		return player != null
			&& WorldPoint.fromLocalInstance(client, player.getLocalLocation()).getRegionID() == INFERNO_REGION;
	}

	private static int toTicks(int seconds)
	{
		// A tick is 0.6 seconds
		return Math.max(0, (seconds * 10 + 5) / 6);
	}

	boolean isOnCooldown()
	{
		return ticksLeft > 0;
	}
}

package com.surgetimer;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("surgetimer")
public interface SurgeTimerConfig extends Config
{
	enum TimeFormat
	{
		SECONDS,
		TICKS
	}

	enum FillDirection
	{
		BOTTOM_UP,
		TOP_DOWN
	}

	@ConfigItem(
		keyName = "fillDirection",
		name = "Fill direction",
		description = "Which way the potion gets its color back as the cooldown runs out",
		position = 1
	)
	default FillDirection fillDirection()
	{
		return FillDirection.BOTTOM_UP;
	}

	@ConfigItem(
		keyName = "timeFormat",
		name = "Time format",
		description = "Show the time left in minutes and seconds, or in game ticks",
		position = 2
	)
	default TimeFormat timeFormat()
	{
		return TimeFormat.SECONDS;
	}
}

package com.surgetimer;

import com.google.common.collect.ImmutableSet;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.AsyncBufferedImage;

class SurgeTimerOverlay extends WidgetItemOverlay
{
	private static final Set<Integer> SURGE_POTIONS = ImmutableSet.of(
		ItemID._4DOSESURGE, ItemID._3DOSESURGE, ItemID._2DOSESURGE, ItemID._1DOSESURGE);
	private static final float SHADE_OPACITY = 0.6f;
	private static final int FADE_ROWS = 4;

	private final SurgeTimerPlugin plugin;
	private final ItemManager itemManager;
	private final SurgeTimerConfig config;
	private final Map<Integer, Shade> shades = new HashMap<>();

	@Inject
	SurgeTimerOverlay(SurgeTimerPlugin plugin, ItemManager itemManager, SurgeTimerConfig config)
	{
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.config = config;
		showOnInventory();
	}

	static boolean isSurgePotion(int itemId)
	{
		return SURGE_POTIONS.contains(itemId);
	}

	void clearCache()
	{
		shades.clear();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!plugin.isOnCooldown() || !SURGE_POTIONS.contains(itemId))
		{
			return;
		}

		int ticksLeft = plugin.getTicksLeft();
		Rectangle bounds = widgetItem.getCanvasBounds();
		Shade shade = getShade(itemId);

		// The potion gets its color back from one end as the cooldown runs out, so the shade only
		// covers the part past the edge. The edge moves over the potion itself rather than the whole
		// item image, which has empty space around it, and fades out over a few rows.
		boolean bottomUp = config.fillDirection() == SurgeTimerConfig.FillDirection.BOTTOM_UP;
		float left = (float) ticksLeft / SurgeTimerPlugin.COOLDOWN_TICKS;
		// How far the shade reaches into the potion, counted from the end it's anchored to
		float reach = (shade.bottom - shade.top + FADE_ROWS) * left - FADE_ROWS / 2f;
		int width = shade.image.getWidth();
		Composite composite = graphics.getComposite();
		for (int row = shade.top; row < shade.bottom; row++)
		{
			float depth = bottomUp ? row - shade.top : shade.bottom - 1 - row;
			float strength = Math.min(1, (reach - depth) / FADE_ROWS + 0.5f);
			if (strength <= 0)
			{
				continue;
			}

			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, strength));
			graphics.drawImage(shade.image,
				bounds.x, bounds.y + row, bounds.x + width, bounds.y + row + 1,
				0, row, width, row + 1, null);
		}
		graphics.setComposite(composite);

		String text = config.timeFormat() == SurgeTimerConfig.TimeFormat.TICKS
			? Integer.toString(ticksLeft)
			: formatTime(ticksLeft);
		graphics.setFont(FontManager.getRunescapeFont());
		FontMetrics metrics = graphics.getFontMetrics();
		int x = bounds.x + (bounds.width - metrics.stringWidth(text)) / 2;
		int y = bounds.y + (bounds.height + metrics.getAscent() - metrics.getDescent()) / 2;

		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(text, x, y);
	}

	private Shade getShade(int itemId)
	{
		return shades.computeIfAbsent(itemId, id ->
		{
			// Item images load asynchronously, so the shade is filled in once it's ready
			AsyncBufferedImage image = itemManager.getImage(id);
			Shade shade = new Shade(new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB));
			image.onLoaded(() ->
			{
				// Black in the shape of the potion, keeping its edges' transparency
				int top = image.getHeight();
				int bottom = 0;
				for (int y = 0; y < image.getHeight(); y++)
				{
					for (int x = 0; x < image.getWidth(); x++)
					{
						int alpha = image.getRGB(x, y) >>> 24;
						shade.image.setRGB(x, y, (int) (alpha * SHADE_OPACITY) << 24);
						if (alpha > 0)
						{
							top = Math.min(top, y);
							bottom = Math.max(bottom, y + 1);
						}
					}
				}

				if (top < bottom)
				{
					shade.top = top;
					shade.bottom = bottom;
				}
			});
			return shade;
		});
	}

	private static class Shade
	{
		private final BufferedImage image;
		// Rows the potion itself takes up in the image
		private int top;
		private int bottom;

		Shade(BufferedImage image)
		{
			this.image = image;
			this.bottom = image.getHeight();
		}
	}

	private static String formatTime(int ticks)
	{
		// A tick is 0.6 seconds, rounded up so it never says 0:00 while still on cooldown
		int seconds = (ticks * 6 + 9) / 10;
		return String.format("%d:%02d", seconds / 60, seconds % 60);
	}
}
